<?php require_once __DIR__.'/seguridad.php';simceRequireRole(array('plataforma_superadmin','colegio_admin','docente'),false);?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Personalización del colegio</title><style>body{font-family:Arial;background:#f1f5f9;color:#172554;padding:24px}.card{max-width:760px;margin:auto;background:#fff;padding:28px;border-radius:16px}label{display:block;font-weight:bold;margin-top:14px}input{width:100%;padding:11px;margin-top:5px;box-sizing:border-box}button{padding:12px;margin-top:20px;background:#1d4ed8;color:white;border:0;border-radius:8px}.preview{display:flex;gap:16px;align-items:center;margin-top:18px}.preview img{width:75px;height:75px;object-fit:contain}.version{position:fixed;right:12px;bottom:8px;color:#64748b}</style></head><body><main class="card"><a href="pruebas_educativas.php">← Volver</a><h1>Personalización del colegio</h1><form id="form"><label>Nombre de la plataforma<input name="nombre_plataforma" required maxlength="80"></label><label>Nombre del establecimiento<input name="nombre_establecimiento" required maxlength="120"></label><label>Subtítulo<input name="subtitulo" required maxlength="120"></label><label>Saludo de portada<input name="saludo" required maxlength="120"></label><label>Texto para elegir perfil<input name="seleccion_perfil" required maxlength="100"></label><label>Logo (PNG, JPG o WebP; máximo 2 MB)<input type="file" name="logo" accept=".png,.jpg,.jpeg,.webp"></label><label>Ícono del navegador / favicon (PNG o ICO; máximo 512 KB)<input type="file" name="favicon" accept=".png,.ico,image/png,image/x-icon"></label><div class="preview"><img id="preview"><div><strong id="brandName"></strong><p id="institution"></p></div></div><button>Guardar cambios</button><p id="message"></p></form></main><div class="version">v2.1.0</div><script src="sesion-cliente.js"></script><script>
const f=document.querySelector('#form'),m=document.querySelector('#message'),schoolCode=new URLSearchParams(location.search).get('colegio')||'';function show(x){Object.keys(x).forEach(k=>{if(f.elements[k]&&!['logo','favicon'].includes(k))f.elements[k].value=x[k]});if(x.logo){preview.src=x.logo;preview.hidden=false}else{preview.removeAttribute('src');preview.hidden=true}brandName.textContent=x.nombre_plataforma;institution.textContent=x.nombre_establecimiento+' — '+x.subtitulo}async function init(){const session=await window.simceGetSession(),x=await fetch('personalizacion_v21_api.php'+(schoolCode?'?colegio='+encodeURIComponent(schoolCode):'')).then(r=>r.json());show(x.marca);if(session.rol==='docente'){Array.from(f.elements).forEach(element=>element.disabled=true);m.textContent='Vista de consulta. Sólo el administrador puede guardar cambios.'}}f.logo.onchange=()=>{if(f.logo.files[0]){preview.src=URL.createObjectURL(f.logo.files[0]);preview.hidden=false}};f.onsubmit=async e=>{e.preventDefault();m.textContent='Guardando…';const data=new FormData(f);if(schoolCode)data.append('colegio',schoolCode);const r=await window.simceAuthenticatedFetch('personalizacion_v21_api.php',{method:'POST',body:data}),x=await r.json();m.textContent=x.ok?'Personalización guardada.':x.error;if(x.ok)show(x.marca)};init().catch(e=>{m.textContent=e.message||'No se pudo cargar la personalización.'});
</script></body></html>
